import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test.describe("manage vendors", () => {
  test(
    "a vendor under review cannot be edited",
    { tag: "@VEN-09" },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor and submits it, moving it to in_review.
      const member = await apiAs("member");
      const created = await expectStatus(
        await member.post("/api/vendors", {
          data: {
            name: uniqueName("VEN-09 Locked Vendor"),
            category: "logistics",
            contact_email: "ops@locked-vendor.example",
          },
        }),
        201,
      );
      const submitted = await expectStatus(
        await member.post(`/api/vendors/${created.id}/submit`),
        200,
      );
      expect(submitted.status).toBe("in_review");

      // Act: attempt to change the contact email while under review.
      const response = await member.patch(`/api/vendors/${created.id}`, {
        data: { contact_email: "billing@acmefreight.example" },
      });

      // Assert: the edit is rejected with a conflict and a stable error code.
      const body = await expectStatus(response, 409);
      expect(body.error.code).toBe("vendor_locked");

      // The stored record is unchanged.
      const current = await expectStatus(await member.get(`/api/vendors/${created.id}`), 200);
      expect(current.contact_email).toBe("ops@locked-vendor.example");
      expect(current.status).toBe("in_review");
    },
  );
});
